         throw new UnsupportedOperationException("Not supported");
     }

     @Override
     public CityResponse maxMindCity(InetAddress ipAddress) throws IOException, GeoIp2Exception {
         throw new UnsupportedOperationException("Not supported");
     }

     @Override
     public void close() throws IOException {
         this.reader.close();
     }
 }

