228.                     map.put("continent", countryResponse.getContinent());
229.                     map.put("country", country);
230.                     map.put("registered_country", countryResponse.getRegisteredCountry());
231.                     map.put("represented_country", countryResponse.getRepresentedCountry());
232.                     map.put("traits", countryResponse.getTraits());
233. 
234.                     final String singleValue = country == null ? null : country.getIsoCode();
235.                     return LookupResult.multi(singleValue, map);
236.                 } catch (AddressNotFoundException nfe) {
237.                     LOG.debug("Unable to look up country data for IP address {}, returning empty result.", addr, nfe);
238.                     return LookupResult.empty();
239.                 } catch (Exception e) {
240.                     LOG.warn("Unable to look up country data for IP address {}, returning empty result.", addr, e);
241.                     return LookupResult.empty();
242.                 }
243.             case MAXMIND_ASN:
244.                 try {
245.                     final AsnResponse asn = reader.maxMindASN(addr);
246.                     if (asn == null) {
247.                         LOG.debug("No ASN data for IP address {}, returning empty result.", addr);
