250.                     final ImmutableMap<Object, Object> map = ImmutableMap.of(
251.                             "as_number", asn.getAutonomousSystemNumber(),
252.                             "as_organization", asn.getAutonomousSystemOrganization()
253.                     );
254.                     return LookupResult.multi(asn.getAutonomousSystemNumber(), map);
255.                 } catch (AddressNotFoundException nfe) {
256.                     LOG.debug("Unable to look up ASN data for IP address {}, returning empty result.", addr, nfe);
257.                     return LookupResult.empty();
258.                 } catch (Exception e) {
259.                     LOG.warn("Unable to look up ASN data for IP address {}, returning empty result.", addr, e);
260.                     return LookupResult.empty();
261.                 }
262.             case IPINFO_ASN:
263.                 try {
