268.                     }
269. 
270.                     // Values can be null so we cannot use an ImmutableMap here
271.                     final Map<Object, Object> multiValue = new HashMap<>();
272.                     multiValue.put("asn", ipInfo.asn());
273.                     multiValue.put("asn_numeric", ipInfo.asnNumeric());
274.                     multiValue.put("name", ipInfo.name());
275.                     multiValue.put("domain", ipInfo.domain());
276.                     multiValue.put("type", ipInfo.type());
277.                     multiValue.put("route", ipInfo.route());
278. 
