280.                 } catch (AddressNotFoundException e) {
281.                     LOG.debug("Unable to look up IPinfo ASN data for IP address {}, returning empty result.", addr, e);
282.                     return LookupResult.empty();
283.                 } catch (Exception e) {
284.                     LOG.warn("Unable to look up IPinfo ASN data for IP address {}, returning empty result.", addr, e);
285.                     return LookupResult.empty();
286.                 }
287.             case IPINFO_STANDARD_LOCATION:
288.                 try {
289.                     final IPinfoStandardLocation ipInfo = reader.ipInfoStandardLocation(addr);
290.                     if (ipInfo == null) {
291.                         LOG.debug("No IPinfo location data for IP address {}, returning empty result.", addr);
292.                         return LookupResult.empty();
293.                     }
294. 
295.                     // Values can be null so we cannot use an ImmutableMap here
296.                     final Map<Object, Object> multiValue = new HashMap<>();
297.                     multiValue.put("coordinates", ipInfo.coordinates());
298.                     multiValue.put("latitude", ipInfo.latitude());
299.                     multiValue.put("longitude", ipInfo.longitude());
300.                     multiValue.put("city", ipInfo.city());
301.                     multiValue.put("country", ipInfo.country());
302.                     multiValue.put("region", ipInfo.region());
303.                     multiValue.put("timezone", ipInfo.timezone());
304.                     multiValue.put("geoname_id", ipInfo.geoNameId());
305. 
306.                     return LookupResult.multi(ipInfo.coordinates(), Collections.unmodifiableMap(multiValue));
307.                 } catch (AddressNotFoundException e) {
308.                     LOG.debug("Unable to look up IPinfo location data for IP address {}, returning empty result.", addr, e);
309.                     return LookupResult.empty();
310.                 } catch (Exception e) {
311.                     LOG.warn("Unable to look up IPinfo location data for IP address {}, returning empty result.", addr, e);
